export function getPhoto(name: string): MenuPhoto | undefined {
  return PHOTOS[name]
}

/** <img src> に使う URL（GitHub Pages のサブパスでも動くよう相対パスで返す） */
export function photoUrl(photo: MenuPhoto): string {
  return import.meta.env.BASE_URL + photo.src
}
